// motor_fault_status: Motor-driver diagnostic status. Ignore detailed flags when status_valid is false; a clear fault input alone does not establish driver health.
#pragma pack(push, 1)
typedef struct
{
    uint8_t sleep_requested; // The sleep control is asserted; reading never wakes the driver.
    uint8_t status_valid; // Driver diagnostic registers were read successfully. Detailed flags are unknown when false.
    uint8_t fault_active; // The fault input is asserted or a valid register reports a global fault.
    uint8_t overtemperature_warning; // Driver temperature warning is reported.
    uint8_t undervoltage; // Driver supply undervoltage is reported; this does not prove a disconnected supply.
    uint8_t charge_pump_undervoltage; // Driver charge-pump undervoltage is reported.
    uint8_t overcurrent; // An overcurrent fault is reported.
    uint8_t overtemperature_shutdown; // A thermal shutdown fault is reported.
    uint8_t open_load; // The configured open-load detector reports a fault; detection depends on operating conditions.
    uint8_t current_regulation; // At least one output reports current regulation; this is not an overcurrent fault.
} motor_fault_status;
#pragma pack(pop)

// motor_fault_sample: Timestamped motor-driver diagnostic status. Timestamp marks completion of the read; faults can be latched rather than new events.
#pragma pack(push, 1)
typedef struct
{
    uint64_t timestamp_us; // ADC read completion timestamp in the selected clock domain.
    uint8_t clock_mode; // 0 uptime, 1 Unix wall time.
    uint8_t clock_quality; // 1 valid, 2 stale.
    uint8_t sleep_requested; // The sleep control is asserted; reading never wakes the driver.
    uint8_t status_valid; // Driver diagnostic registers were read successfully. Detailed flags are unknown when false.
    uint8_t fault_active; // The fault input is asserted or a valid register reports a global fault.
    uint8_t overtemperature_warning; // Driver temperature warning is reported.
    uint8_t undervoltage; // Driver supply undervoltage is reported; this does not prove a disconnected supply.
    uint8_t charge_pump_undervoltage; // Driver charge-pump undervoltage is reported.
    uint8_t overcurrent; // An overcurrent fault is reported.
    uint8_t overtemperature_shutdown; // A thermal shutdown fault is reported.
    uint8_t open_load; // The configured open-load detector reports a fault; detection depends on operating conditions.
    uint8_t current_regulation; // At least one output reports current regulation; this is not an overcurrent fault.
} motor_fault_sample;
#pragma pack(pop)

